  const flat = parseArgs(argv);
  const out = {};
  for (const [path, raw] of Object.entries(flat)) {
    if (!isKnownLeaf(path)) continue;
    const value = coerce(path, raw);
    if (value !== undefined) setPath(out, path, value);
