Cursor pagination must be stable when `createdAt` is not unique and new rows appear at the top. The offset path is kept byte-for-byte identical for legacy clients. Presence of `page` and `cursor` is detected via `!== undefined` so an empty string `?cursor=` still counts as cursor mode. Mutual exclusivity is checked first, then shared `pageSize` parsing. In cursor mode an empty cursor means first page; otherwise the cursor is decoded with `decodeCursor` and any failure is mapped to `ApiError(400, 'invalid cursor')`. The decoded payload is validated to contain numeric `createdAt` and `id` to reject tampered objects like `{}`. Items are obtained via `db.listAll()` which already sorts by `createdAt desc, id desc`. Filtering uses the classic keyset condition `createdAt < cursor.createdAt OR (createdAt == cursor.createdAt AND id < cursor.id)` to avoid skipping or repeating rows when equal timestamps straddle a boundary. The page is the first `pageSize` filtered rows; `nextCursor` is `encodeCursor({createdAt, id})` of the last row if more rows remain, otherwise exactly `null`, which also covers the exactly-full last page case. No mutation of `query` or DB rows occurs.

```mjs
// src/api.mjs
import { ApiError } from './errors.mjs';
import { encodeCursor, decodeCursor } from './cursor.mjs';

export const DEFAULT_PAGE_SIZE = 20;
export const MAX_PAGE_SIZE = 100;

export function parsePageSize(raw) {
  if (raw === undefined) return DEFAULT_PAGE_SIZE;
  const n = Number(raw);
  if (!Number.isInteger(n) || n < 1 || n > MAX_PAGE_SIZE) {
    throw new ApiError(400, `pageSize must be an integer between 1 and ${MAX_PAGE_SIZE}`);
  }
  return n;
}

/**
 * GET /items
 * @param {import('./db.mjs').ItemsDb} db
 * @param {Record<string, string>} query  raw query-string values
 */
export function listItems(db, query = {}) {
  const hasPage = query.page !== undefined;
  const hasCursor = query.cursor !== undefined;

  if (hasPage && hasCursor) {
    throw new ApiError(400, 'page and cursor are mutually exclusive');
  }

  const pageSize = parsePageSize(query.pageSize);

  if (hasCursor) {
    // cursor mode
    const rawCursor = query.cursor;

    let cursorObj = null;
    if (rawCursor !== '') {
      try {
        const decoded = decodeCursor(rawCursor);
        // Validate shape: must contain numeric createdAt and id
        if (
          typeof decoded.createdAt !== 'number' ||
          !Number.isFinite(decoded.createdAt) ||
          typeof decoded.id !== 'number' ||
          !Number.isFinite(decoded.id)
        ) {
          throw new Error('bad cursor');
        }
        cursorObj = decoded;
      } catch {
        throw new ApiError(400, 'invalid cursor');
      }
    }

    const all = db.listAll();

    let filtered;
    if (cursorObj === null) {
      filtered = all;
    } else {
      const cCreatedAt = cursorObj.createdAt;
      const cId = cursorObj.id;
      filtered = all.filter((row) => {
        if (row.createdAt < cCreatedAt) return true;
        if (row.createdAt === cCreatedAt && row.id < cId) return true;
        return false;
      });
    }

    const pageItems = filtered.slice(0, pageSize);
    let nextCursor = null;
    if (filtered.length > pageSize) {
      const last = pageItems[pageItems.length - 1];
      nextCursor = encodeCursor({ createdAt: last.createdAt, id: last.id });
    }

    return { items: pageItems, nextCursor };
  }

  // legacy offset mode - keep byte-for-byte
  const page = query.page === undefined ? 1 : Number(query.page);
  if (!Number.isInteger(page) || page < 1) throw new ApiError(400, 'page must be a positive integer');
  const all = db.listAll();
  const start = (page - 1) * pageSize;
  return { items: all.slice(start, start + pageSize), page, pageSize, total: all.length };
}
