// Generic async retry helper.
//
// Options:
//   retries      number of retries AFTER the first attempt (default 3)
//   baseDelayMs  delay before the first retry (default 100)
//   factor       exponential backoff multiplier (default 2)
//   sleep        (ms, signal) => Promise, injectable for tests
//   signal       optional AbortSignal; aborting cancels further attempts
//
// fn receives the zero-based attempt index.

export function defaultSleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason);
      return;
    }
    const t = setTimeout(resolve, ms);
    signal?.addEventListener('abort', () => {
      clearTimeout(t);
      reject(signal.reason);
    }, { once: true });
  });
}

export async function retry(fn, opts = {}) {
  const { retries = 3, baseDelayMs = 100, factor = 2, sleep = defaultSleep, signal } = opts;

  if (signal?.aborted) {
    throw signal.reason;
  }

  let lastErr;
  for (let attempt = 0; attempt <= retries; attempt++) {
    if (signal?.aborted) {
      throw signal.reason;
    }
    try {
      return await fn(attempt);
    } catch (err) {
      lastErr = err;

      if (signal?.aborted) {
        throw signal.reason;
      }

      if (err && err.retryable === false) {
        throw err;
      }

      if (attempt === retries) {
        break;
      }

      const delay = baseDelayMs * Math.pow(factor, attempt);

      if (signal?.aborted) {
        throw signal.reason;
      }

      try {
        if (signal) {
          if (signal.aborted) {
            throw signal.reason;
          }
          let onAbort;
          const abortPromise = new Promise((_, reject) => {
            onAbort = () => reject(signal.reason);
            signal.addEventListener('abort', onAbort, { once: true });
          });
          let sleepPromise;
          try {
            sleepPromise = sleep(delay, signal);
          } catch (syncErr) {
            signal.removeEventListener('abort', onAbort);
            throw syncErr;
          }
          try {
            await Promise.race([sleepPromise, abortPromise]);
          } finally {
            signal.removeEventListener('abort', onAbort);
            // Prevent unhandled rejection if abort wins and sleep later rejects
            sleepPromise.catch(() => {});
          }
        } else {
          await sleep(delay, signal);
        }
      } catch (sleepErr) {
        if (signal?.aborted) {
          throw signal.reason;
        }
        throw sleepErr;
      }
    }
  }
  throw lastErr;
}

