export function buildInvoice(lines, { taxBps }) {
  if (!Number.isInteger(taxBps) || taxBps < 0) throw new RangeError('taxBps must be a non-negative integer');
  const out = lines.map((l) => {
    const netCents = l.qty * l.unitCents;
    const taxCents = bankersRoundDiv(netCents * taxBps, 10000);
    return { sku: l.sku, qty: l.qty, unitCents: l.unitCents, netCents, taxCents };
  });
  const subtotalCents = out.reduce((s, l) => s + l.netCents, 0);
  const taxCents = out.reduce((s, l) => s + l.taxCents, 0);
  return { lines: out, subtotalCents, taxCents, totalCents: subtotalCents + taxCents, taxBps };
}

function bankersRoundDiv(numerator, denominator) {
  if (numerator === 0) return 0;
  const sign = Math.sign(numerator);
  const absNum = Math.abs(numerator);
  let q;
  let r;
  if (Number.isInteger(absNum) && Number.isInteger(denominator)) {
    q = Math.trunc(absNum / denominator);
    r = absNum % denominator;
  } else {
    q = Math.floor(absNum / denominator);
    r = absNum - q * denominator;
  }
  const half = denominator / 2;
  const EPS = 1e-12;
  let absResult;
  if (Math.abs(r - half) < EPS) {
    // tie -> round to even
    absResult = (q % 2 === 0) ? q : q + 1;
  } else if (r < half) {
    absResult = q;
  } else {
    absResult = q + 1;
  }
  if (absResult === 0) return 0;
  return absResult * sign;
}

